with.script:
for (const name of ["secret-scan", "next-public-secrets"]) {
  await github.rest.repos.createCommitStatus({
    ...context.repo, sha: context.payload.pull_request.head.sha,
    context: name, state: 'pending', description: `${name} is evaluating this pull request`,
  });
}

const results = JSON.parse(process.env.RESULTS);
const pr = context.payload.pull_request;
const sha = pr.head.sha;
const canPublish = context.actor !== 'dependabot[bot]' && pr.user.login !== 'dependabot[bot]' &&
  pr.head.repo.full_name === `${context.repo.owner}/${context.repo.repo}`;
const guards = [["secret-scan", "gitleaks"], ["next-public-secrets", "public-secrets"]];
let failed = false;
for (const [name, id] of guards) {
  const passed = results[id]?.outcome === 'success' &&
    (name !== 'secret-scan' || results.trufflehog?.outcome === 'success');
  failed ||= !passed;
  if (!canPublish) continue;
  const { data: current } = await github.rest.pulls.get({
    ...context.repo, pull_number: pr.number,
  });
  if (current.head.sha !== sha) continue;
  await github.rest.repos.createCommitStatus({
    ...context.repo, sha,
    context: name, state: passed ? 'success' : 'failure',
    description: passed ? `${name} passed` : `${name} failed or did not run`,
    target_url: `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`,
  });
}
if (failed) core.setFailed('One or more guards failed.');

const eventPr = context.payload.pull_request;
for (const name of ["outside-pr-guard", "pr-size", "pr-title"]) {
  if (eventPr.base.ref !== 'production' && name !== 'outside-pr-guard') continue;
  const { data: current } = await github.rest.pulls.get({
    ...context.repo, pull_number: eventPr.number,
  });
  if (current.head.sha !== eventPr.head.sha ||
      (name === 'pr-title' && current.title !== eventPr.title)) continue;
  await github.rest.repos.createCommitStatus({
    ...context.repo, sha: eventPr.head.sha,
    context: name, state: 'pending', description: `${name} is evaluating this pull request`,
  });
}

const marker = '<!-- pr-size-warning -->';
const cap = 400;
const botLogin = 'github-actions[bot]';

async function run() {
  const prNumber = context.payload.pull_request?.number;
  if (!prNumber) {
    core.info('No pull_request payload; skipping pr-size check.');
    return;
  }

  // Fetch fresh from the API rather than trust the webhook payload.
  const { data: pr } = await github.rest.pulls.get({
    ...context.repo,
    pull_number: prNumber,
  });

  core.setOutput('sha', pr.head.sha);

  // This repo has no fork contributors; skip explicitly and visibly rather
  // than silently commenting on a fork PR we don't intend to support.
  if (pr.head.repo.full_name !== `${context.repo.owner}/${context.repo.repo}`) {
    core.info(`PR #${pr.number} is from a fork (${pr.head.repo.full_name}); skipping pr-size comment.`);
    return;
  }

  const total = (pr.additions || 0) + (pr.deletions || 0);
  const over = total > cap;

  let body;
  if (over) {
    body = `${marker}\n\n:warning: **PR size warning** — this PR is **${total}** changed lines (additions + deletions), over the ~${cap}-line cap in AGENTS.md. Consider splitting it into a stack of small PRs: each builds green and is safe to merge alone, landed in order. The cap is advisory — this comment never blocks merging.`;
  } else {
    body = `${marker}\n\n:white_check_mark: This PR is now **${total}** changed lines (additions + deletions), within the ~${cap}-line cap in AGENTS.md.`;
  }

  const comments = await github.paginate(github.rest.issues.listComments, {
    ...context.repo,
    issue_number: pr.number,
  });
  const existing = comments.find((c) => c.user?.login === botLogin && (c.body || '').includes(marker));

  if (over) {
    if (existing) {
      if (existing.body !== body) {
        await github.rest.issues.updateComment({
          ...context.repo,
          comment_id: existing.id,
          body,
        });
        core.info(`Updated size comment for PR #${pr.number}.`);
      } else {
        core.info(`Size comment for PR #${pr.number} is already up to date.`);
      }
    } else {
      await github.rest.issues.createComment({
        ...context.repo,
        issue_number: pr.number,
        body,
      });
      core.info(`Created size comment for PR #${pr.number}.`);
    }
  } else if (existing) {
    await github.rest.issues.updateComment({
      ...context.repo,
      comment_id: existing.id,
      body,
    });
    core.info(`Updated size comment to within-cap for PR #${pr.number}.`);
  } else {
    core.info(`PR #${pr.number} is within the cap and has no size comment; nothing to do.`);
  }
}

try {
  await run();
} catch (err) {
  core.warning(`pr-size check failed but will not block the PR: ${err.message}`);
}

const results = JSON.parse(process.env.RESULTS);
const eventPr = context.payload.pull_request;
const guards = [["outside-pr-guard", "outside"], ["pr-size", "size"], ["pr-title", "title"]];
let failed = false;
for (const [name, id] of guards) {
  if (eventPr.base.ref !== 'production' && id !== 'outside') continue;
  const result = results[id];
  const sha = result?.outputs?.sha || eventPr.head.sha;
  const title = result?.outputs?.title ?? eventPr.title;
  const { data: current } = await github.rest.pulls.get({
    ...context.repo, pull_number: eventPr.number,
  });
  if (current.head.sha !== eventPr.head.sha || current.head.sha !== sha ||
      (id === 'title' && current.title !== title)) {
    core.info(`Skipping stale ${name} verdict; a newer run owns it.`);
    continue;
  }
  const passed = result?.outcome === 'success' && Boolean(result.outputs?.sha);
  failed ||= !passed;
  await github.rest.repos.createCommitStatus({
    ...context.repo, sha,
    context: name, state: passed ? 'success' : 'failure',
    description: passed ? `${name} passed` : `${name} failed or did not run`,
    target_url: `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`,
  });
}
if (failed) core.setFailed('One or more guards failed.');
